/**
 * Wire model for hydra's polymorphic `AgentTool` GraphQL interface,
 * surfaced through antman's `getAgent` endpoint
 * (`antman/.../agent/AgentClient.java`'s GraphQL fragment).
 *
 * Mirrors antman's flat-union `AgentTool` Java record: every
 * variant-specific field is optional on the wire, populated based on
 * `type`. Same convention as the EDK's `Agent` wire model — the
 * discriminator is a closed string-literal union; consumers narrow on
 * `type` to safely access variant-specific fields. Antman aliases
 * hydra's GraphQL `__typename` to `type` so the GraphQL-y field name
 * doesn't leak into the REST surface.
 *
 * Variant coverage matches antman's MR (ECP-14495). One known gap:
 * `AgentSelectBotRouteTool` carries only the base-interface fields
 * because hydra's read-side GraphQL doesn't expose the bot reference
 * — round-trip support for that variant requires a separate hydra
 * change.
 */
import type { AgentConversationRunAs } from "./agent.js";
/**
 * Closed set of `AgentTool` variants — mirrors hydra's
 * `@JsonSubTypes` discriminators on the agent-tool union. Round-trip
 * support exists for every variant except `AgentSelectBotRouteTool`
 * (see module-level note).
 */
export type AgentToolType = "AgentSearchAspectTool" | "AgentSearchTableTool" | "AgentCreateRecordTool" | "AgentUpdateRecordTool" | "AgentRelateRecordTool" | "AgentSelectBotRouteTool" | "AgentExecuteWorkflowTool" | "AgentRunAgentTool" | "AgentMcpTool";
/**
 * One field entry on an agent tool's `fields[]` array — covers
 * `AgentSearchFieldTool`, `AgentRecordCreateFieldTool`, and
 * `AgentRecordUpdateFieldTool` from hydra. The wire shape is
 * structurally identical across the three variants once
 * `field: AspectField` is normalized; `required` and `defaultValue`
 * are populated only on the create/update variants.
 *
 * Distinct from skill-side `AgentFieldTool` which uses a flat
 * `fieldId: UUID` — that's the skill GraphQL convention. Agent-side
 * nests the field reference instead.
 */
export interface AgentToolField {
    readonly field?: {
        readonly id: string;
    };
    readonly name: string;
    readonly description: string;
    readonly required?: boolean;
    readonly defaultValue?: string;
}
/**
 * Reference to a workflow trigger parameter — id and name. Returned
 * as part of {@link AgentExecuteWorkflowInputParameter} on
 * `AgentExecuteWorkflowTool.inputs[].triggerParameter`.
 */
export interface WorkflowTriggerParameterRef {
    readonly id: string;
    readonly name?: string;
}
/**
 * Reference to a workflow output property — id only. Returned as
 * part of {@link AgentExecuteWorkflowOutputParameter} on
 * `AgentExecuteWorkflowTool.outputs[].workflowOutputProperty`.
 */
export interface WorkflowOutputPropertyRef {
    readonly id: string;
}
/**
 * One input parameter on `AgentExecuteWorkflowTool`. The
 * `triggerParameter` reference resolves to a parameter the target
 * automation declares on its on-demand trigger; `triggerParameter.name`
 * matches the parameter's declared name and is what the EDK builder
 * accepts at deploy time (the runtime resolver also accepts UUIDs).
 */
export interface AgentExecuteWorkflowInputParameter {
    readonly name: string;
    readonly description: string;
    readonly triggerParameter: WorkflowTriggerParameterRef;
    readonly required?: boolean;
    readonly multiple?: boolean;
}
/**
 * One output parameter on `AgentExecuteWorkflowTool`. The
 * `workflowOutputProperty` reference resolves to a workflow output
 * declared on the target automation.
 */
export interface AgentExecuteWorkflowOutputParameter {
    readonly name: string;
    readonly workflowPropertyName: string;
    readonly workflowOutputProperty?: WorkflowOutputPropertyRef;
}
/**
 * One HTTP header attached to an `AgentMcpTool`'s outbound request.
 */
export interface AgentToolHeader {
    readonly key: string;
    readonly value: string;
}
/**
 * Polymorphic agent-tool wire shape. `type` is the discriminator;
 * only the fields a given variant supplies are populated. Every
 * variant carries the shared identity bookkeeping (`id`, `name`,
 * `description`, `startMessage`, `runAs`).
 *
 * Variant-to-fields map (every field optional, populated per `type`):
 *
 * | type                        | extra fields                                                    |
 * |-----------------------------|-----------------------------------------------------------------|
 * | AgentSearchAspectTool       | aspect, fields, filter, sort, limit, queryDescription           |
 * | AgentSearchTableTool        | aspect, table, fields, filter, limit, queryDescription          |
 * | AgentCreateRecordTool       | aspect, fields                                                  |
 * | AgentUpdateRecordTool       | aspect, fields, handleDescription                               |
 * | AgentRelateRecordTool       | aspect, relatedAspect                                           |
 * | AgentSelectBotRouteTool     | (none — bot reference not exposed by hydra read-side GraphQL)   |
 * | AgentExecuteWorkflowTool    | automation, inputs, outputs, timeout                            |
 * | AgentRunAgentTool           | targetAgent, workerTaskPrompt                                   |
 * | AgentMcpTool                | serverUrl, mcpToolName, headers                                 |
 *
 * `filter` / `sort` / `limit` round-trip on agent search tools through
 * the same shared infrastructure automation `recordSearch` uses (see
 * `pull/normalize-filter.ts`, `pull/print-filter.ts`,
 * `core/filters/serialize.ts`, `core/types/common.ts:serializeSortToWire`).
 * Wire types are typed against the platform's `Filter` / `Sort`
 * shapes; B2.5 wires them through normalize → AST → printer so a
 * pulled file emits a `filter: (row) => ...` callback that the EDK
 * builder accepts on re-deploy.
 *
 * Note: `aspect.__typename` and `relatedAspect.__typename` retain
 * the GraphQL-y name because the apps/aspect wire surface still uses
 * `__typename` (apps-side rename is out of scope for B2).
 */
export interface AgentTool {
    readonly type?: AgentToolType;
    readonly id: string;
    readonly name: string;
    readonly description: string;
    readonly startMessage?: string;
    readonly runAs?: AgentConversationRunAs;
    readonly aspect?: {
        readonly id: string;
        readonly __typename?: string;
    };
    readonly relatedAspect?: {
        readonly id: string;
        readonly __typename?: string;
    };
    readonly table?: {
        readonly id: string;
    };
    readonly fields?: readonly AgentToolField[];
    /**
     * Wire `Filter` — the platform's polymorphic filter JSON, typed
     * against the same canonical `Filter` source authors use. The serializer's
     * `structuredClone` pass-through means wire and source shapes are
     * structurally identical; the deserializer walks this through
     * `pull/normalize-filter.ts:normalizeFilter` to resolve references in place
     * the printer can render as a typed `(row) => ...` callback.
     */
    readonly filter?: import("../../../../src/entities/shared/filters/types.js").Filter;
    /**
     * Wire `Sort` shape — `{ orders: [{ field: <fieldId>, direction }] }`.
     * Authored as `SortOrder | readonly SortOrder[]` on the EDK side and
     * serialized via `core/types/common.ts:serializeSortToWire`.
     */
    readonly sort?: {
        readonly orders: ReadonlyArray<{
            readonly field: string;
            readonly direction: "ASC" | "DESC";
        }>;
    };
    readonly limit?: number;
    readonly queryDescription?: string;
    readonly handleDescription?: string;
    readonly automation?: {
        readonly id: string;
        readonly name?: string;
    };
    readonly inputs?: readonly AgentExecuteWorkflowInputParameter[];
    readonly outputs?: readonly AgentExecuteWorkflowOutputParameter[];
    readonly timeout?: string;
    readonly targetAgent?: {
        readonly id: string;
        readonly name?: string;
        readonly type?: string;
    };
    readonly workerTaskPrompt?: string;
    readonly serverUrl?: string;
    readonly mcpToolName?: string;
    readonly headers?: readonly AgentToolHeader[];
}
